const p = $('Parámetros').first().json;
const eventos = $('Leer eventos de Zoom').all().map(i => i.json).filter(e => e && e.evento);
const fsAlumnos = $('Leer alumnos (Firestore)').all().map(i => i.json).filter(a => a && a._id);
const sesion = $('Leer sesión').first().json || {};
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();

// 1) Qué reunión de Zoom usar: la indicada, o la última que terminó
let meetingId = p.meetingId;
if (!meetingId && eventos.length) {
  const ord = [...eventos].sort((a, b) => String(b.recibido).localeCompare(String(a.recibido)));
  meetingId = (ord.find(e => e.evento === 'meeting.ended') || ord[0]).meetingId;
}
const evs = eventos.filter(e => meetingId && String(e.meetingId) === String(meetingId));

// 2) Minutos por participante (entradas y salidas)
const porPersona = {};
const partEvs = evs.filter(e => String(e.evento).startsWith('meeting.participant')).sort((a, b) => String(a.hora).localeCompare(String(b.hora)));
for (const e of partEvs) {
  const key = e.participanteEmail ? norm(e.participanteEmail) : 'nombre:' + norm(e.participanteNombre);
  const r = porPersona[key] || (porPersona[key] = { email: norm(e.participanteEmail), nombre: norm(e.participanteNombre), minutos: 0, entrada: null });
  const t = Date.parse(e.hora);
  if (e.evento === 'meeting.participant_joined') r.entrada = isNaN(t) ? null : t;
  if (e.evento === 'meeting.participant_left' && r.entrada && !isNaN(t)) { r.minutos += (t - r.entrada) / 60000; r.entrada = null; }
}
const fin = evs.find(e => e.evento === 'meeting.ended');
const tFin = fin ? Date.parse(fin.hora) : NaN;
for (const r of Object.values(porPersona)) if (r.entrada && !isNaN(tFin)) { r.minutos += (tFin - r.entrada) / 60000; r.entrada = null; }
const registros = Object.values(porPersona);
const manual = new Set((p.asistentesEmails || []).map(norm));

// 3) Tarea de referencia: ahora viene de la sesión sincronizada desde la web real (ya no de Moodle)
const cursoIdSesion = sesion.cursoId || 'PBI-2026';
const tarea = sesion.tareaNombre ? {
  nombre: sesion.tareaNombre,
  fechaEntrega: sesion.tareaFechaEntrega || '',
  enunciado: sesion.tareaEnunciado || '',
  entregaron: [] // la web real aún no expone "quién entregó" por API; ver nota en el sticky
} : null;

// 4) Roster: los alumnos ya registrados en Firestore para este curso/sesión (antes venía de Moodle)
const candidatos = fsAlumnos.filter(a => String(a.cursoId) === String(cursoIdSesion) || String(a.sesionActualId) === String(p.sesionId));
const base = candidatos.length ? candidatos : fsAlumnos.filter(a => a.telefono || a._id);
const lista = base.map((a, idx) => {
  const email = norm(a.email);
  const reg = registros.find(r => (email && r.email === email) || (r.nombre && r.nombre === norm(a.nombre)));
  const asistio = Boolean(reg) || (email && manual.has(email));
  return {
    idx,
    nombre: a.nombre,
    email: a.email || '',
    telefono: a._id,
    moodleId: a.moodleId || '',
    asistio: Boolean(asistio),
    minutos: reg ? Math.round(reg.minutos) : 0,
    entregoTarea: tarea ? (tarea.entregaron || []).includes(a.nombre) : false,
    apodo: a.apodo || String(a.nombre || '').split(' ')[0],
    tono: a.tono || 'cercano y motivador',
    cursoId: a.cursoId || cursoIdSesion,
    dmcCoins: Number(a.dmcCoins) || 0,
    asistencias: Number(a.asistencias) || 0,
    ultimaSesionPremiada: a.ultimaSesionPremiada || '',
    parejaPrev: a.parejaTelefono || ''
  };
});

// 5) Parejas: se respeta la guardada; si no existe, se emparejan en orden (1-2, 3-4, ...)
const tels = new Set(lista.map(a => a.telefono).filter(Boolean));
for (const al of lista) {
  let pt = al.parejaPrev;
  if (!pt || !tels.has(pt) || pt === al.telefono) {
    const compa = lista[al.idx % 2 === 0 ? al.idx + 1 : al.idx - 1];
    pt = compa ? compa.telefono : '';
  }
  al.parejaTelefono = pt || '';
  delete al.parejaPrev;
}

const fuente = registros.length ? 'zoom' : (manual.size ? 'manual' : 'sin datos');
return [{ json: {
  sesionId: p.sesionId,
  meetingId: meetingId || '',
  fuenteAsistencia: fuente,
  eventosUsados: evs.length,
  titulo: sesion.titulo || p.sesionId,
  transcripcion: sesion.transcripcion || '',
  resumenPrevio: sesion.resumen || '',
  tareaRef: tarea,
  asistentes: lista.filter(a => a.asistio).map(a => a.nombre),
  ausentes: lista.filter(a => !a.asistio).map(a => a.nombre),
  alumnos: lista
} }];

parameters.text:
=Eres el asistente académico de DMC Institute. A partir SOLO de la transcripción de la clase, genera:
1) "resumen": 3 o 4 ideas clave, cada una de máximo 20 palabras, citando el minuto [mm:ss] si aparece.
2) "ejercicios": 3 ejercicios cortos de práctica (niveles básico, intermedio, reto) con una pista que no dé la respuesta.

Reglas: no inventes temas que no estén en la transcripción. Los ejercicios deben ser DISTINTOS a la tarea calificada (no la resuelvas ni la parafrasees). Escribe en español neutro y claro.

CLASE: {{ $json.titulo }}

TAREA CALIFICADA (no resolver): {{ $json.tareaRef ? $json.tareaRef.nombre + " — " + $json.tareaRef.enunciado : "ninguna" }}

TRANSCRIPCIÓN:
{{ $json.transcripcion || $json.resumenPrevio }}

