const c = $('Cruzar asistencia').first().json;
const ia = $input.first().json.output || {};
return [{ json: {
  sesionId: c.sesionId,
  titulo: c.titulo,
  meetingId: c.meetingId,
  fuenteAsistencia: c.fuenteAsistencia,
  resumen: ia.resumen || [],
  ejercicios: ia.ejercicios || [],
  asistentes: c.asistentes,
  ausentes: c.ausentes,
  totalAlumnos: c.alumnos.length,
  totalAsistentes: c.asistentes.length,
  generado: new Date().toISOString()
} }];

const c = $('Cruzar asistencia').first().json;
const clase = $('Datos de la clase').first().json;
const bullets = (clase.resumen || []).slice(0, 4).map(b => '• ' + b).join('\n');
const ejercicio = (clase.ejercicios || [])[0];
const porTel = Object.fromEntries(c.alumnos.filter(a => a.telefono).map(a => [a.telefono, a]));
const primerNombre = (n) => String(n || '').split(' ')[0];
const fecha = c.tareaRef ? String(c.tareaRef.fechaEntrega || '').replace(/\.$/, '') : '';
const out = [];

for (const a of c.alumnos) {
  if (!a.telefono) continue;
  const pareja = a.parejaTelefono ? porTel[a.parejaTelefono] : null;
  const yaPremiado = a.ultimaSesionPremiada === c.sesionId;
  const gana = a.asistio && !yaPremiado ? 10 : 0;
  const coins = a.dmcCoins + gana;

  let tareaLinea = '';
  if (c.tareaRef) {
    if (a.entregoTarea) tareaLinea = '✅ Ya entregaste ' + c.tareaRef.nombre + '. ¡Crack!';
    else {
      const fechaTxt = fecha ? (' vence el ' + fecha) : '';
      tareaLinea = '📌 Tu ' + c.tareaRef.nombre + fechaTxt + '.' +
        (pareja && pareja.entregoTarea
          ? ' ' + primerNombre(pareja.nombre) + ' (tu pareja) ya lo entregó, ¡tú también puedes! 💪'
          : ' Si te trabas, escríbeme y te doy una pista (sin darte la respuesta 😉).');
    }
  }

  let mensaje;
  if (a.asistio) {
    mensaje = (gana ? '¡Bien ahí, ' + a.apodo + '! Estuviste en *' + c.titulo + '* y sumaste +10 DMC-coins 🪙 (llevas ' + coins + ').'
                    : '¡Bien ahí, ' + a.apodo + '! Llevas ' + coins + ' DMC-coins 🪙.') +
      (bullets ? '\n\nLo clave de hoy:\n' + bullets : '') +
      (ejercicio ? '\n\n🧩 Reto rápido: ' + ejercicio.enunciado : '') +
      (tareaLinea ? '\n\n' + tareaLinea : '');
  } else {
    mensaje = a.apodo + ', hoy te extrañamos en *' + c.titulo + '* 😕' +
      (bullets ? '\nAquí lo clave en 1 minuto:\n' + bullets : '') +
      '\n\n🎥 La grabación y el resumen ya están en tu aula.' +
      (pareja && pareja.asistio ? '\n🤝 ' + primerNombre(pareja.nombre) + ' sí estuvo: pregúntale cómo le fue o escríbeme tus dudas.' : '') +
      (tareaLinea ? '\n\n' + tareaLinea : '');
  }

  out.push({ json: {
    telefono: a.telefono,
    nombre: a.nombre,
    apodo: a.apodo,
    tono: a.tono,
    email: a.email || '',
    moodleId: a.moodleId,
    cursoId: a.cursoId,
    parejaTelefono: a.parejaTelefono,
    sesionActualId: c.sesionId,
    dmcCoins: coins,
    asistencias: a.asistencias + (gana ? 1 : 0),
    ultimaSesionPremiada: a.asistio ? c.sesionId : a.ultimaSesionPremiada,
    tipo: a.asistio ? 'asistio' : 'falto',
    entregoTarea: a.entregoTarea,
    mensaje
  } });
}
return out;

const c = $('Cruzar asistencia').first().json;
const clase = $('Datos de la clase').first().json;
const mensajes = $('Armar mensajes por alumno').all().map(i => ({ nombre: i.json.nombre, telefono: i.json.telefono, tipo: i.json.tipo, dmcCoins: i.json.dmcCoins, mensaje: i.json.mensaje }));
return [{ json: {
  ok: true,
  sesionId: c.sesionId,
  meetingId: c.meetingId,
  fuenteAsistencia: c.fuenteAsistencia,
  asistentes: c.asistentes,
  ausentes: c.ausentes,
  resumen: clase.resumen,
  ejercicios: clase.ejercicios,
  mensajes
} }];
